// Generate the interactive map's basemap layer array from the Protomaps
// `light` theme, with our PNG palette layered on top and label layers
// suppressed. Output is a plain JS module (js/views/basemap-layers.js)
// that map-interactive.js imports synchronously.
//
// Run this whenever js/views/map-palette.js changes, or when we upgrade
// protomaps-themes-base:
//
//     npm run build:basemap
//
// Then commit the generated file. It's not regenerated on every prod
// build — the palette is stable, and diffing the output on unrelated
// deploys would be noisy.
//
// Node ≥ 20 (for ESM + import.meta.url). Tested on 26.4.
//
// KEEP IN SYNC: the theme override + building-outline paint values in
// this script are IMPORTED from js/views/map-palette.js — that module
// is the single source of truth for the illustrated PNG palette.

import { writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, resolve } from 'node:path';
import { createRequire } from 'node:module';

import {
    BASEMAP_THEME_OVERRIDE,
    BUILDING_OUTLINE_PAINT,
    PALETTE,
} from '../js/views/map-palette.js';

// protomaps-themes-base ships as CJS. Use createRequire to load it from
// this ESM context without spelunking through its internals.
const require = createRequire(import.meta.url);
const themes = require('protomaps-themes-base');

const HERE = dirname(fileURLToPath(import.meta.url));
const OUT_PATH = resolve(HERE, '..', 'js', 'views', 'basemap-layers.js');

// The `light` flavor is our starting point — its layer topology (road
// hierarchy, tunnel/bridge casings, per-zoom fill opacities) is what
// gives the illustrated map its density. We override the ~30 color
// slots that show at zoom 15 and inherit the rest.
const baseTheme = themes.namedTheme('light');
const theme = { ...baseTheme, ...BASEMAP_THEME_OVERRIDE };

// noLabelsWithCustomTheme skips every symbol layer (place labels,
// road labels, POI icons, water labels). We paint from geojson
// overlays instead — no place labels for villages, no beach POI
// icons clashing with our festival iconography.
const layers = themes.noLabelsWithCustomTheme('basemap', theme);

// Building outline sits on top of the whole stack so building
// footprints (from source-layer:'buildings') get a thin dark stroke
// for definition against the magenta land.
layers.push({
    id: 'buildings_outline',
    source: 'basemap',
    'source-layer': 'buildings',
    type: 'line',
    filter: ['in', 'kind', 'building', 'building_part'],
    paint: {
        'line-color': BUILDING_OUTLINE_PAINT.color,
        'line-width': BUILDING_OUTLINE_PAINT.width,
        'line-opacity': BUILDING_OUTLINE_PAINT.opacity,
    },
});

const banner = [
    '// AUTO-GENERATED by scripts/generate-basemap-layers.mjs — do not edit.',
    '//',
    '// Source: protomaps-themes-base@' + require('protomaps-themes-base/package.json').version + '::noLabelsWithCustomTheme("basemap", …)',
    '// Palette source: js/views/map-palette.js (BASEMAP_THEME_OVERRIDE)',
    '// Total layers: ' + layers.length,
    '// Anchor palette: canvasDeep=' + PALETTE.canvasDeep + ', earth=' + PALETTE.landMid + ', water=' + PALETTE.waterMain,
    '//',
    '// To regenerate:  npm run build:basemap',
    '',
    'export default ' + JSON.stringify(layers, null, 2) + ';',
    '',
].join('\n');

writeFileSync(OUT_PATH, banner);
console.log('✅ wrote', OUT_PATH.replace(process.cwd() + '/', ''), '(' + layers.length + ' layers)');
